INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'rihla-travels-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Rihla Voyages in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من رحلة للسياحة في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IATA-accredited travel agency designing bespoke cultural itineraries, group retreats, and corporate aviation bookings. Focusing on 7-Day Boutique Cultural Itinerary, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"وكالة سفر معتمدة من أياتا تصمم البرامج السياحية المخصصة ورحلات الأعمال وحجوزات الطيران. من خلال خدمة برنامج سياحي ثقافي لمدة 7 أيام نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>IATA-accredited travel agency designing bespoke cultural itineraries, group retreats, and corporate aviation bookings.</p><p>Focusing on <strong>7-Day Boutique Cultural Itinerary</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>وكالة سفر معتمدة من أياتا تصمم البرامج السياحية المخصصة ورحلات الأعمال وحجوزات الطيران.</p><p>من خلال خدمة <strong>برنامج سياحي ثقافي لمدة 7 أيام</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Rihla Voyages', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | رحلة للسياحة', 'Executive guide by Rihla Voyages covering 7-Day Boutique Cultural Itinerary benchmarks in Bahrain.', 'دليل تنفيذي من رحلة للسياحة حول معايير برنامج سياحي ثقافي لمدة 7 أيام في البحرين.', 'Sustainability', '{"travel","sustainability","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
